// Pure transforms embedded in the reviewed JSON by build-refine.cjs. No I/O or tools.
const OWNER_ID = 202449424;
const REPOSITORY = 'MBroholm/software-factory';
const STATES = ['Ideas', 'Refining', 'Ready for approval', 'Approved', 'Building', 'Your QA', 'Done', 'Waiting for you', 'Stuck'];
const PROMPT_VERSION = 'v3';
const TEMPLATE_VERSION = 'v1';
const lf = value => String(value ?? '').replace(/\r\n?/g, '\n');
function bytes(text) {
  return Array.from(encodeURIComponent(text).replace(/%([0-9A-F]{2})/g, (_, h) => String.fromCharCode(parseInt(h, 16))), c => c.charCodeAt(0));
}
// FIPS 180-4 SHA-256 over UTF-8. Avoids enabling module/host access in n8n Code.
function sha256(text) {
  const data = bytes(text), bitLength = data.length * 8;
  data.push(128);
  while (data.length % 64 !== 56) data.push(0);
  for (let i = 7; i >= 0; i--) data.push(Math.floor(bitLength / 2 ** (i * 8)) & 255);
  const k = [], h = [];
  for (let n = 2; k.length < 64; n++) {
    let prime = true;
    for (let d = 2; d * d <= n; d++) if (n % d === 0) { prime = false; break; }
    if (prime) {
      if (h.length < 8) h.push((Math.sqrt(n) % 1 * 2 ** 32) | 0);
      k.push((Math.cbrt(n) % 1 * 2 ** 32) | 0);
    }
  }
  const r = (x, n) => (x >>> n) | (x << (32 - n));
  for (let offset = 0; offset < data.length; offset += 64) {
    const w = [];
    for (let i = 0; i < 16; i++) w[i] = (data[offset+4*i]<<24)|(data[offset+4*i+1]<<16)|(data[offset+4*i+2]<<8)|data[offset+4*i+3];
    for (let i = 16; i < 64; i++) w[i] = (w[i-16] + (r(w[i-15],7)^r(w[i-15],18)^(w[i-15]>>>3)) + w[i-7] + (r(w[i-2],17)^r(w[i-2],19)^(w[i-2]>>>10))) | 0;
    let [a,b,c,d,e,f,g,j] = h;
    for (let i = 0; i < 64; i++) {
      const t1 = (j + (r(e,6)^r(e,11)^r(e,25)) + ((e&f)^(~e&g)) + k[i] + w[i]) | 0;
      const t2 = ((r(a,2)^r(a,13)^r(a,22)) + ((a&b)^(a&c)^(b&c))) | 0;
      [j,g,f,e,d,c,b,a] = [g,f,e,(d+t1)|0,c,b,a,(t1+t2)|0];
    }
    [a,b,c,d,e,f,g,j].forEach((v,i) => { h[i] = (h[i]+v)|0; });
  }
  return h.map(v => (v>>>0).toString(16).padStart(8,'0')).join('');
}
function demand(condition, message) { if (!condition) throw Error(message); }
function state(issue) {
  demand(Number.isSafeInteger(issue.number) && Array.isArray(issue.labels), 'Invalid issue');
  const labels = issue.labels.map(l => typeof l === 'string' ? l : l.name);
  const managed = labels.filter(l => STATES.includes(l));
  demand(managed.length === 1, 'Missing/conflicting task states; owner recovery required');
  demand(!['Waiting for you','Stuck'].includes(managed[0]), 'Unsupported Basic A state');
  return managed[0];
}
function eligible(issue) {
  return !issue.pull_request && issue.user?.id === OWNER_ID && issue.state === 'open';
}
function discover(issues) {
  demand(new Set(issues.map(i => i.number)).size === issues.length, 'Duplicate issue page entries; inspect pagination');
  const result = [];
  for (const issue of issues) {
    if (!eligible(issue)) continue;
    // Unlabelled ordinary repository issues are not factory tasks.
    if (!issue.labels?.some(l => STATES.includes(typeof l === 'string' ? l : l.name))) continue;
    const current = state(issue);
    demand(current !== 'Refining', 'Stranded Refining; no automatic resumption');
    if (['Ideas','Ready for approval'].includes(current)) result.push(issue);
  }
  return result.sort((a,b) => a.number-b.number);
}
function factoryComment(comment) {
  return /^(?:<!--\s*)?factory:[a-z][a-z0-9_-]*:v1\b/.test(lf(comment.body));
}
function canonical(issue, comments) {
  return JSON.stringify({title:lf(issue.title), body:lf(issue.body), owner_comments:comments.map(c => ({id:c.id,body:lf(c.body)})).sort((a,b) => a.id-b.id)});
}
function source(issue, comments) {
  const ids = comments.map(c => c.id).sort((a,b) => a-b);
  demand(new Set(ids).size === ids.length && ids.every(id => Number.isSafeInteger(id) && id > 0), 'Invalid captured IDs');
  const source_digest = sha256(canonical(issue, comments));
  const last_included_owner_comment_id = ids.at(-1) ?? 0;
  return {issue_number:issue.number, source_digest, captured_comment_ids:ids, last_included_owner_comment_id,
    prompt_version:PROMPT_VERSION, template_version:TEMPLATE_VERSION,
    source_key:`${issue.number}:${source_digest}:${last_included_owner_comment_id}:${PROMPT_VERSION}`};
}
function history(comments, issue) {
  const revisions = [];
  for (const comment of comments) {
    if (!/^<!-- factory:refinement:v1\b/.test(lf(comment.body))) continue;
    demand(comment.user?.id === OWNER_ID, 'Untrusted refinement marker; inspect manually');
    const match = lf(comment.body).match(/^<!-- factory:refinement:v1 (\{[^\n]+\}) -->\n([\s\S]*)$/);
    demand(match, 'Malformed refinement marker');
    let meta; try { meta = JSON.parse(match[1]); } catch { throw Error('Malformed refinement metadata'); }
    demand(meta.issue_number === issue.number && /^[a-f0-9]{64}$/.test(meta.source_digest)
      && /^[a-f0-9]{64}$/.test(meta.content_sha256) && meta.content_sha256 === sha256(match[2])
      && Array.isArray(meta.captured_comment_ids) && meta.captured_comment_ids.every(Number.isSafeInteger)
      && new Set(meta.captured_comment_ids).size === meta.captured_comment_ids.length
      && meta.captured_comment_ids.every((id,i,a) => id > 0 && (i === 0 || id > a[i-1]))
      && meta.last_included_owner_comment_id === (meta.captured_comment_ids.at(-1) ?? 0)
      && /^v\d+$/.test(meta.prompt_version) && /^v\d+$/.test(meta.template_version)
      && meta.source_key === `${issue.number}:${meta.source_digest}:${meta.last_included_owner_comment_id}:${meta.prompt_version}`,
    'Edited/invalid refinement evidence');
    demand(Number.isSafeInteger(comment.id) && Number.isFinite(Date.parse(comment.created_at))
      && comment.created_at === comment.updated_at, 'Edited refinement comment; inspect manually');
    revisions.push({comment,meta});
  }
  revisions.sort((a,b) => a.comment.id-b.comment.id);
  demand(new Set(revisions.map(r => r.meta.source_key)).size === revisions.length, 'Duplicate refinement markers');
  return revisions;
}
function pages(items) {
  const result = [];
  demand(items.length > 0 && items.length < 100, 'Pagination cap reached; inspect before processing');
  for (const item of items) {
    demand(item.statusCode === 200 && Array.isArray(item.body), 'Invalid paginated response');
    result.push(...item.body);
  }
  const last = items.at(-1);
  demand(!/rel="next"/.test(last.headers?.link ?? '') && last.body.length < 100, 'Incomplete pagination');
  return result;
}
// Pure US2 policy, packaged with the unchanged US1 canonical-source helpers.
function reservationCandidates(issues) {
  demand(new Set(issues.map(i=>i.number)).size===issues.length,'Duplicate issue pages');
  // Closed, non-owner and conflicting Building tasks also reserve the slot.
  if (issues.some(i=>!i.pull_request && i.labels?.some(l=>(typeof l==='string'?l:l.name)==='Building'))) return [];
  return issues.filter(i=>eligible(i) && i.labels?.some(l=>(typeof l==='string'?l:l.name)==='Approved'))
    .map(i=>{demand(state(i)==='Approved','Conflicting approval state');return i;}).sort((a,b)=>a.number-b.number);
}
function approval(issue,comments,events,expectedState='Approved') {
  demand(eligible(issue) && state(issue)===expectedState,'Issue no longer eligible');
  demand(new Set(comments.map(c=>c.id)).size===comments.length,'Duplicate comments');
  demand(new Set(events.map(e=>e.id)).size===events.length,'Duplicate approval history');
  const relevant=events.filter(e=>['labeled','unlabeled'].includes(e.event) && e.label?.name==='Approved').sort((a,b)=>a.id-b.id);
  demand(relevant.every(e=>Number.isSafeInteger(e.id) && Number.isFinite(Date.parse(e.created_at))),'Invalid approval history');
  // After our transition, the last Approved event is our removal, not new approval.
  if(expectedState==='Building') {
    const removed=relevant.pop(); demand(removed?.event==='unlabeled' && removed.actor?.id===OWNER_ID,'Approval removal missing');
  }
  const event=relevant.at(-1);
  demand(event?.event==='labeled' && event.actor?.id===OWNER_ID,'Missing current explicit owner approval');
  const latest=history(comments,issue).at(-1);
  demand(latest,'Missing successful refinement');
  demand(Date.parse(latest.comment.created_at)<Date.parse(event.created_at)
    && Date.parse(latest.comment.updated_at)<Date.parse(event.created_at),'Refinement not before approval');
  demand(latest.comment.html_url===`https://github.com/${REPOSITORY}/issues/${issue.number}#issuecomment-${latest.comment.id}`,'Invalid refinement URL');
  const included=latest.meta.captured_comment_ids.map(id=>{
    const c=comments.find(c=>c.id===id);
    demand(c?.user?.id===OWNER_ID && !factoryComment(c) && typeof c.body==='string','Captured source missing/changed');return c;
  });
  demand(source(issue,included).source_digest===latest.meta.source_digest,'Approved source edited/deleted');
  return {issue_number:issue.number,approval_event_id:event.id,approval_actor_id:event.actor.id,approval_timestamp:event.created_at,
    refinement_comment_id:latest.comment.id,refinement_url:latest.comment.html_url,
    refinement_created_at:latest.comment.created_at,refinement_updated_at:latest.comment.updated_at,
    refinement_content_sha256:latest.meta.content_sha256,refinement_body_sha256:sha256(latest.comment.body),
    source_digest:latest.meta.source_digest,branch:`issue-${issue.number}`};
}
function sameApproval(original,current) {
  demand(JSON.stringify(original)===JSON.stringify(current),'Approval/refinement/source changed; inspect manually');
}
function baseline(pulls,number) {
  demand(new Set(pulls.map(p=>p.number)).size===pulls.length,'Duplicate PR pages');
  return pulls.filter(p=>p.head?.repo?.full_name===REPOSITORY && p.head.ref===`issue-${number}` && p.base?.ref==='main').map(p=>{
    demand(Number.isSafeInteger(p.number) && /^[0-9a-f]{40}$/.test(p.head.sha) && ['open','closed'].includes(p.state),'Invalid PR baseline');
    return {number:p.number,head_sha:p.head.sha,state:p.state};
  }).sort((a,b)=>a.number-b.number);
}
function checkHandoffs(comments,plan) {
  for(const c of comments) {
    if(!/^<!-- factory:handoff:v1\b/.test(lf(c.body))) continue;
    const m=lf(c.body).match(/^<!-- factory:handoff:v1 (\{[^\n]+\}) -->\n/);
    demand(m && c.user?.id===OWNER_ID && c.created_at===c.updated_at,'Invalid/edited handoff; manual recovery');
    let meta;try{meta=JSON.parse(m[1]);}catch{throw Error('Malformed handoff');}
    demand(meta.issue_number===plan.issue_number && Number.isSafeInteger(meta.approval_event_id),'Invalid handoff metadata');
    demand(meta.approval_event_id!==plan.approval_event_id,'Approval already handed off; manual recovery');
  }
}
function handoff(plan,prs,timestamp) {
  demand(Number.isFinite(Date.parse(timestamp)),'Invalid handoff timestamp');
  const metadata={...plan,baseline_prs:baseline(prs,plan.issue_number),timestamp};
  const body=`<!-- factory:handoff:v1 ${JSON.stringify(metadata)} -->\n## Manual build reservation\n\nIssue: https://github.com/${REPOSITORY}/issues/${plan.issue_number}\nApproved refinement: ${plan.refinement_url}\nApproval event: ${plan.approval_event_id} (${plan.approval_timestamp}); owner actor ${plan.approval_actor_id}.\nRefinement content SHA-256: ${plan.refinement_content_sha256}\nSource SHA-256: ${plan.source_digest}\nBranch: \`${plan.branch}\`; base: \`main\`.\n\nBuilding reserves the single slot; it does not confirm Codex has started. The owner must verify this approved input and launch Codex manually on Fedora using docs/manual-coding.md. Ask result-changing questions in the session and summarize answers/decisions on this issue. Expanded scope requires fresh explicit approval. Return changes in a linked pull request with actual checks and unchecked criteria. No agent was launched by this workflow.\n`;
  return {metadata,body};
}

const candidates=reservationCandidates(pages($input.all().map(i=>i.json)));
return [{json:{issue:candidates[0]??null}}];

